window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9f8ab432fb8eacf7"]={"versions": [{"id": "FIG-9f8ab432fb8eacf7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Textuelle Spezifikationsbox (AUTOSAR Constraint Definition) im Kontext der semantischen Validierungsebene (Semantic Level) des AUTOSAR-Werkzeugaustauschs gemäß AUTOSAR_TR_InteroperabilityOfAutosarTools. Das Schaubild visualisiert die formale Definition einer semantischen Metamodell-Bedingung über reine XML-Schema-Gültigkeit hinaus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Definierte Entitäten und Metamodell-Elemente:</p>\n<ul class=\"fig-list\">\n<li><code>[constr_1031]</code>: Eindeutiger Bezeichner des semantischen Constraints mit dem Titel <code>NvBlockSwComponentType references ConstantSpecificationMappingSet</code>.</li>\n<li><code>NvBlockSwComponentType</code>: AUTOSAR Software-Komponententyp für den Zugriff auf nichtflüchtigen Speicher (NVRAM).</li>\n<li><code>ConstantSpecificationMappingSet</code>: Spezifikationsmenge für Konstantendefinitionen bzw. -zuordnungen.</li>\n<li><code>NvBlockDescriptor</code>: Aggregiertes Element innerhalb des <code>NvBlockSwComponentType</code>.</li>\n</ul>\n<p class=\"fig-p\">Semantische Verknüpfung: Wenn ein <code>NvBlockSwComponentType</code> auf ein <code>ConstantSpecificationMappingSet</code> referenziert, ist dieses dem aggregierten <code>NvBlockDescriptor</code> zugeordnet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches semantisches Regelwerk ohne zeitlichen Ablauf. Die Validierung greift während der Modellprüfung bzw. des Imports/Exports in Autorenwerkzeugen: Beim Vorliegen einer Referenz von <code>NvBlockSwComponentType</code> auf ein <code>ConstantSpecificationMappingSet</code> erzwingt die semantische Schicht die Konsistenzprüfung, ob die Zuordnung mit dem zugehörigen aggregierten <code>NvBlockDescriptor</code> übereinstimmt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative semantische Integritätsbedingung für AUTOSAR-Autorenwerkzeuge: Autorenwerkzeuge müssen sicherstellen, dass über die reine syntaktische XML-Validität hinaus die Konsistenzregel <code>[constr_1031]</code> implementiert und geprüft wird, um semantische Kompatibilität beim werkzeugübergreifenden Modellaustausch zu garantieren.</p>"}, {"id": "FIG-5c256d59b967a8c0", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Textuelle Spezifikationsbox (AUTOSAR Constraint Definition) im Kontext der semantischen Validierungsebene (Semantic Level) des AUTOSAR-Werkzeugaustauschs gemäß AUTOSAR_TR_InteroperabilityOfAutosarTools. Das Schaubild visualisiert die formale Definition einer semantischen Metamodell-Bedingung über reine XML-Schema-Gültigkeit hinaus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Definierte Entitäten und Metamodell-Elemente:</p>\n<ul class=\"fig-list\">\n<li><code>[constr_1031]</code>: Eindeutiger Bezeichner des semantischen Constraints mit dem Titel <code>NvBlockSwComponentType references ConstantSpecificationMappingSet</code>.</li>\n<li><code>NvBlockSwComponentType</code>: AUTOSAR Software-Komponententyp für den Zugriff auf nichtflüchtigen Speicher (NVRAM).</li>\n<li><code>ConstantSpecificationMappingSet</code>: Spezifikationsmenge für Konstantendefinitionen bzw. -zuordnungen.</li>\n<li><code>NvBlockDescriptor</code>: Aggregiertes Element innerhalb des <code>NvBlockSwComponentType</code>.</li>\n</ul>\n<p class=\"fig-p\">Semantische Verknüpfung: Wenn ein <code>NvBlockSwComponentType</code> auf ein <code>ConstantSpecificationMappingSet</code> referenziert, ist dieses dem aggregierten <code>NvBlockDescriptor</code> zugeordnet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches semantisches Regelwerk ohne zeitlichen Ablauf. Die Validierung greift während der Modellprüfung bzw. des Imports/Exports in Autorenwerkzeugen: Beim Vorliegen einer Referenz von <code>NvBlockSwComponentType</code> auf ein <code>ConstantSpecificationMappingSet</code> erzwingt die semantische Schicht die Konsistenzprüfung, ob die Zuordnung mit dem zugehörigen aggregierten <code>NvBlockDescriptor</code> übereinstimmt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative semantische Integritätsbedingung für AUTOSAR-Autorenwerkzeuge: Autorenwerkzeuge müssen sicherstellen, dass über die reine syntaktische XML-Validität hinaus die Konsistenzregel <code>[constr_1031]</code> implementiert und geprüft wird, um semantische Kompatibilität beim werkzeugübergreifenden Modellaustausch zu garantieren.</p>"}, {"id": "FIG-bbd43fa3d9441dac", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Textuelle Spezifikationsbox (AUTOSAR Constraint Definition) im Kontext der semantischen Validierungsebene (Semantic Level) des AUTOSAR-Werkzeugaustauschs gemäß AUTOSAR_TR_InteroperabilityOfAutosarTools. Das Schaubild visualisiert die formale Definition einer semantischen Metamodell-Bedingung über reine XML-Schema-Gültigkeit hinaus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Definierte Entitäten und Metamodell-Elemente:</p>\n<ul class=\"fig-list\">\n<li><code>[constr_1031]</code>: Eindeutiger Bezeichner des semantischen Constraints mit dem Titel <code>NvBlockSwComponentType references ConstantSpecificationMappingSet</code>.</li>\n<li><code>NvBlockSwComponentType</code>: AUTOSAR Software-Komponententyp für den Zugriff auf nichtflüchtigen Speicher (NVRAM).</li>\n<li><code>ConstantSpecificationMappingSet</code>: Spezifikationsmenge für Konstantendefinitionen bzw. -zuordnungen.</li>\n<li><code>NvBlockDescriptor</code>: Aggregiertes Element innerhalb des <code>NvBlockSwComponentType</code>.</li>\n</ul>\n<p class=\"fig-p\">Semantische Verknüpfung: Wenn ein <code>NvBlockSwComponentType</code> auf ein <code>ConstantSpecificationMappingSet</code> referenziert, ist dieses dem aggregierten <code>NvBlockDescriptor</code> zugeordnet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches semantisches Regelwerk ohne zeitlichen Ablauf. Die Validierung greift während der Modellprüfung bzw. des Imports/Exports in Autorenwerkzeugen: Beim Vorliegen einer Referenz von <code>NvBlockSwComponentType</code> auf ein <code>ConstantSpecificationMappingSet</code> erzwingt die semantische Schicht die Konsistenzprüfung, ob die Zuordnung mit dem zugehörigen aggregierten <code>NvBlockDescriptor</code> übereinstimmt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative semantische Integritätsbedingung für AUTOSAR-Autorenwerkzeuge: Autorenwerkzeuge müssen sicherstellen, dass über die reine syntaktische XML-Validität hinaus die Konsistenzregel <code>[constr_1031]</code> implementiert und geprüft wird, um semantische Kompatibilität beim werkzeugübergreifenden Modellaustausch zu garantieren.</p>"}], "trans": [{"from": "FIG-9f8ab432fb8eacf7", "to": "FIG-5c256d59b967a8c0", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5c256d59b967a8c0", "to": "FIG-bbd43fa3d9441dac", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
